<script setup>
import { onMounted, ref } from 'vue';import { listDeadlines, completeDeadline } from '../../../api/deadline';import { session } from '../../../utils/session';import { formatDate,text,tagType } from '../../../utils/enums';import { ElMessage } from 'element-plus'
const props=defineProps({caseId:Number});const list=ref([]);const load=async()=>list.value=(await listDeadlines({caseId:props.caseId,pageSize:100})).data.list;const complete=async(id)=>{await completeDeadline(id);ElMessage.success('任务已完成');load()};onMounted(load)
</script>
<template><section class="tab-panel"><el-table :data="list"><el-table-column prop="taskName" label="任务" min-width="190"/><el-table-column prop="deadlineType" label="类型"/><el-table-column label="官方期限" width="155"><template #default="{row}">{{formatDate(row.officialDeadline)}}</template></el-table-column><el-table-column label="优先级" width="80"><template #default="{row}">{{text('priority',row.priority)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{text('deadlineStatus',row.status)}}</el-tag></template></el-table-column><el-table-column v-if="session.user.role==='AGENT'" width="80"><template #default="{row}"><el-button v-if="row.status!=='COMPLETED'" link type="success" @click="complete(row.id)">完成</el-button></template></el-table-column></el-table></section></template>
